import os
import zipfile
import io
from flask import Flask, request, send_file, jsonify

app = Flask(__name__)

@app.route('/convert', methods=['POST'])
def convert():
    if 'file' not in request.files:
        return jsonify({"error": "No file part"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "No selected file"}), 400

    if not file.filename.endswith('.zip'):
        return jsonify({"error": "File is not a zip file"}), 400

    try:
        zip_stream = io.BytesIO(file.read())
        text_parts = []
        with zipfile.ZipFile(zip_stream, 'r') as zf:
            for name in zf.namelist():
                if name.endswith('.txt') or name.endswith('.py') or name.endswith('.js') or name.endswith('.ts') or name.endswith('.java') or name.endswith('.c') or name.endswith('.h') or name.endswith('.cpp') or name.endswith('.hpp') or name.endswith('.cs') or name.endswith('.rb') or name.endswith('.go') or name.endswith('.rs') or name.endswith('.swift') or name.endswith('.kt') or name.endswith('.sh') or name.endswith('.css') or name.endswith('.html'):
                    try:
                        content = zf.read(name).decode('utf-8')
                        text_parts.append(content)
                    except Exception:
                        continue
        result = "\n\n".join(text_parts)
        return result, 200, {'Content-Type': 'text/plain'}
    except zipfile.BadZipFile:
        return jsonify({"error": "Invalid zip file"}), 400
    except Exception as e:
        return jsonify({"error": str(e)}), 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
